    /// Each fixture in `payload.invalid-examples.json` MUST be
    /// rejected by at least one of: serde deserialization, or
    /// JSON-Schema validation under the `validate` feature. The
    /// fixture file documents the producer-side bug class that
    /// each payload exemplifies; this generated test pins it.
    #[cfg(feature = "validate")]
    #[test]
    fn rejects_invalid_examples() {
        use crate::validate::ValidatedPayload;
        let fixtures: &[(&str, &str)] = &[
            (
                "No target at all — the oneOf requires exactly one of `sessionId`, `all` and `subject`.",
                "{\n  \"reason\": \"logout\"\n}",
            ),
            (
                "`sessionId` and `all` together — mutually exclusive.",
                "{\n  \"all\": true,\n  \"sessionId\": \"ec5d3c89-3f49-49b2-9d7d-2a8c0a8a7b9b\"\n}",
            ),
            (
                "`subject` and `sessionId` together — mutually exclusive. A producer cannot scope a single-session revoke to a subject; the session names its own subject.",
                "{\n  \"sessionId\": \"ec5d3c89-3f49-49b2-9d7d-2a8c0a8a7b9b\",\n  \"subject\": \"did:web:alice.example\"\n}",
            ),
            (
                "`subject` and `all` together — mutually exclusive, and ambiguous about whose sessions are meant.",
                "{\n  \"all\": true,\n  \"subject\": \"did:web:alice.example\"\n}",
            ),
            (
                "`subject` must be a DID — a bare handle would let the consumer guess which party is meant.",
                "{\n  \"subject\": \"alice\"\n}",
            ),
            (
                "Unknown top-level payload member.",
                "{\n  \"frobnicate\": true,\n  \"subject\": \"did:web:alice.example\"\n}",
            ),
        ];
        for (i, (note, raw)) in fixtures.iter().enumerate() {
            let value: serde_json::Value = match serde_json::from_str(raw) {
                Ok(v) => v,
                Err(_) => continue,
            };
            let serde_ok = serde_json::from_value::<super::Payload>(value.clone()).is_ok();
            let schema_ok = super::Payload::validate_value(&value).is_ok();
            assert!(
                !(serde_ok && schema_ok),
                "invalid-example #{} ({:?}) was accepted by both serde and JSON Schema; \
                         the fixture's stated failure class is no longer caught:\n{}",
                i + 1,
                note,
                raw
            );
        }
    }
